import UIKit

final class OrdersViewController: UITableViewController {
    private var orders: [Order] = []

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        orders.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "OrderCell", for: indexPath)
        let order = orders[indexPath.row]
        let dateFormatter = DateFormatter()
        dateFormatter.dateStyle = .medium
        let priceFormatter = NumberFormatter()
        priceFormatter.numberStyle = .currency
        priceFormatter.currencyCode = order.currency
        var content = cell.defaultContentConfiguration()
        content.text = "Order #\(order.number)"
        content.secondaryText = "\(dateFormatter.string(from: order.placedAt)) · \(priceFormatter.string(from: order.total as NSNumber) ?? "")"
        cell.contentConfiguration = content
        return cell
    }
}

