func mentions(in messages: [Message]) -> [String] {
    messages.flatMap { message -> [String] in
        guard let regex = try? NSRegularExpression(pattern: "@([A-Za-z0-9_]{2,30})") else { return [] }
        let range = NSRange(message.text.startIndex..., in: message.text)
        return regex.matches(in: message.text, range: range).compactMap {
            Range($0.range(at: 1), in: message.text).map { String(message.text[$0]) }
        }
    }
}

