import Foundation

struct WorkoutRowFormatter {
    func durationText(for workout: Workout) -> String {
        let formatter = DateComponentsFormatter()
        formatter.allowedUnits = [.hour, .minute]
        formatter.unitsStyle = .abbreviated
        return formatter.string(from: workout.duration) ?? "--"
    }

    func distanceText(for workout: Workout) -> String {
        let formatter = MeasurementFormatter()
        formatter.unitOptions = .naturalScale
        return formatter.string(from: Measurement(value: workout.meters, unit: UnitLength.meters))
    }
}

